insert into auth.users(id,email,email_confirmed_at) select ('00000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'avatar'||n||'@example.test',now() from generate_series(70,74)n;
insert into public.profiles(user_id,full_name) select id,'Avatar person '||right(id::text,2) from auth.users where email like 'avatar%@example.test';
insert into public.organizations(id,name) values('10000000-0000-0000-0000-000000000070','Avatar A'),('10000000-0000-0000-0000-000000000071','Avatar B');
insert into public.organization_memberships(id,organization_id,user_id,email,role)
select ('20000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,case when n<73 then '10000000-0000-0000-0000-000000000070' else '10000000-0000-0000-0000-000000000071' end::uuid,('00000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'avatar'||n||'@example.test',case when n in(70,73) then 'manager' else 'employee' end from generate_series(70,74)n;
set role authenticated;
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000071';
insert into test.codes values('avatar-path',public.reserve_profile_photo('81000000-0000-4000-8000-000000000071'));
select test.ok(public.reserve_profile_photo('81000000-0000-4000-8000-000000000071')=(select code from test.codes where label='avatar-path'),'photo reservation is idempotent for its owner');
select test.rejects($q$select public.set_my_profile_photo('81000000-0000-4000-8000-000000000071')$q$,'Finish uploading','photo cannot be selected before upload');
insert into storage.objects(bucket_id,name) select 'profile-photos',code from test.codes where label='avatar-path';
select test.ok((select count(*) from storage.objects where bucket_id='profile-photos')=1,'owner can upload and read pending photo');
select test.rejects($q$insert into storage.objects(bucket_id,name)values('profile-photos','unreserved.jpg')$q$,'row-level security','unreserved avatar uploads denied');
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000072';
select test.ok((select count(*) from storage.objects where bucket_id='profile-photos')=0,'teammate cannot read an unpublished avatar');
select test.rejects($q$select public.reserve_profile_photo('81000000-0000-4000-8000-000000000071')$q$,'Photo is not available','another user cannot claim a reserved photo ID');
select test.rejects($q$select public.set_my_profile_photo('81000000-0000-4000-8000-000000000071')$q$,'Photo is not available','another user cannot select someone else photo');
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000071';
select public.set_my_profile_photo('81000000-0000-4000-8000-000000000071');
select test.ok((select avatar_path=(select code from test.codes where label='avatar-path') from public.profiles where user_id=auth.uid()),'photo pointer is saved on own profile');
select test.ok(public.set_my_profile_photo('81000000-0000-4000-8000-000000000071')->>'object_name'=(select code from test.codes where label='avatar-path'),'lost response can safely retry selecting the current photo');
with changed as(update storage.objects set name=name||'.new' where bucket_id='profile-photos' returning id) select test.ok((select count(*) from changed)=0,'published avatar cannot be overwritten or renamed');
with removed as(delete from storage.objects where bucket_id='profile-photos' returning id) select test.ok((select count(*) from removed)=0,'current avatar cannot be deleted behind profile pointer');
select public.create_team_corner_post('10000000-0000-0000-0000-000000000070','91000000-0000-4000-8000-000000000071','A profile photo test');
select public.create_team_corner_comment('91000000-0000-4000-8000-000000000071','92000000-0000-4000-8000-000000000071','An avatar comment');
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000072';
select test.ok((select count(*) from storage.objects where bucket_id='profile-photos')=1,'active teammate can read current avatar');
select test.ok(public.get_team_corner('10000000-0000-0000-0000-000000000070')->'posts'->0->>'avatar_path'=(select code from test.codes where label='avatar-path'),'existing post includes current author avatar');
select test.ok(public.get_team_corner('10000000-0000-0000-0000-000000000070')->'posts'->0->'comments'->0->>'avatar_path'=(select code from test.codes where label='avatar-path'),'comment includes current author avatar');
with removed as(delete from storage.objects where bucket_id='profile-photos' returning id) select test.ok((select count(*) from removed)=0,'teammate cannot remove another photo');
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000070';
select test.ok(exists(select 1 from jsonb_array_elements(public.get_training_workspace('10000000-0000-0000-0000-000000000070')->'members')m where m->>'id'='20000000-0000-0000-0000-000000000071' and m->>'avatar_path'=(select code from test.codes where label='avatar-path')),'manager roster includes current avatar without changing training visibility');
select test.ok(exists(select 1 from jsonb_array_elements(public.get_training_workspace('10000000-0000-0000-0000-000000000070')->'lifetime_standings')m where m->>'membership_id'='20000000-0000-0000-0000-000000000071' and m->>'avatar_path'=(select code from test.codes where label='avatar-path')),'lifetime standings include current avatar');
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000001';
select test.ok((select count(*) from storage.objects where bucket_id='profile-photos')=1,'admin profile access can show published avatar for training support');
select test.ok(public.get_team_corner('10000000-0000-0000-0000-000000000070')->>'can_read'='false','avatar access does not grant admin access to store conversation');
reset role;
update public.organization_memberships set status='inactive',deactivated_at=now() where id='20000000-0000-0000-0000-000000000072';
set role authenticated;
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000072';
select test.ok((select count(*) from storage.objects where bucket_id='profile-photos')=0,'removed employee cannot read former teammate avatar');
reset role;
update public.organization_memberships set status='active',deactivated_at=null where id='20000000-0000-0000-0000-000000000072';
set role authenticated;
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000074';
select test.ok((select count(*) from storage.objects where bucket_id='profile-photos')=0,'another store cannot read avatar');
select test.ok((select count(*) from public.profiles where avatar_path is not null)=0,'other store cannot enumerate profile avatar pointers');
select test.rejects($q$select * from private.profile_photos$q$,'permission denied','photo reservations cannot be enumerated');
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000071';
insert into test.codes values('avatar-replacement',public.reserve_profile_photo('81000000-0000-4000-8000-000000000072'));
insert into storage.objects(bucket_id,name) select 'profile-photos',code from test.codes where label='avatar-replacement';
select public.set_my_profile_photo('81000000-0000-4000-8000-000000000072');
select test.rejects($q$select public.set_my_profile_photo('81000000-0000-4000-8000-000000000071')$q$,'Photo is not available','retired avatar cannot be selected again');
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000072';
select test.ok((select count(*) from storage.objects where bucket_id='profile-photos')=1,'replaced avatar becomes unreadable to teammates');
select test.ok(public.get_team_corner('10000000-0000-0000-0000-000000000070')->'posts'->0->>'avatar_path'=(select code from test.codes where label='avatar-replacement'),'existing posts follow replacement photo');
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000071';
select public.set_my_profile_photo(null);
delete from storage.objects where bucket_id='profile-photos';
select test.ok((select count(*) from storage.objects where bucket_id='profile-photos')=0,'owner can clean up old photo files after removal');
select test.ok((select avatar_path is null from public.profiles where user_id=auth.uid()),'remove restores no-photo fallback without changing profile name');
select test.rejects($q$insert into storage.objects(bucket_id,name)select 'profile-photos',code from test.codes where label='avatar-path'$q$,'row-level security','retired photo path cannot be reused with different bytes');
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000072';
select test.ok(public.get_team_corner('10000000-0000-0000-0000-000000000070')->'posts'->0->>'avatar_path' is null,'removed photo is no longer returned on posts');
reset role;
select test.ok(not has_function_privilege('anon','public.reserve_profile_photo(uuid)','execute'),'anonymous upload reservation denied');
select test.ok(not has_function_privilege('authenticated','private.training_workspace_before_avatars(uuid)','execute'),'training report wrapper cannot be bypassed');
select 'Passed profile avatar privacy, upload ownership, replacement/removal, feed and training integration ('||count(*)||' total SQL assertions).' from test.results;
